select
    src.KEY_HASH as KEY_HASH,
    w070._V070 as W070_POLICY_NUMBER,
    w070._N070 as W070_N
from src
left join (
    select
        c0.KEY_HASH as _JK070,
        max(c1.POLICY_NUMBER) as _V070,
        count(*) as _N070
    from {{ ref('hop_uwr_memd_tabs') }} c0
    join {{ ref('stg_uwr') }} c1
        on c0.PARENT_KEY_HASH = c1.KEY_HASH   /* real level 1 */
    group by c0.KEY_HASH
) w070 on src.PARENT_KEY_HASH = w070._JK070
